"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[67063],{69481(e){e.exports=JSON.parse('{"tag":{"label":"accessibility","permalink":"/tips/tags/accessibility","allTagsPath":"/tips/tags","count":2,"items":[{"id":"check-accessibility/62-check-accessibility","title":"How to Check Accessibility with axe","description":"Images without alt text, fields without labels, and buttons without names keep people who use screen readers out. The test can scan the page with axe and fail when it finds problems like these.","permalink":"/tips/62-check-accessibility"},{"id":"find-by-role/59-find-by-role","title":"How to Find Elements by Role and Name","description":"IDs and CSS classes change when the page is redesigned, and many widgets don\'t have them. The role and the name of an element, as a screen reader announces them, change less often, and finding elements by them also checks that the page is accessible.","permalink":"/tips/59-find-by-role"}],"unlisted":false}}')}}]);